import { PromptInput, type PromptInputSendDetail } from '@absoluteui/components/prompt-input';

const host = document.createElement('div');
document.body.append(host);
PromptInput.create(host, { label: 'Message', hideLabel: true, placeholder: 'Ask a question', showHint: true });
host.addEventListener('aui-send', (event) => {
  const { text } = (event as CustomEvent<PromptInputSendDetail>).detail;
  host.dataset.lastSent = text;
});

