import { PromptInput } from '@absoluteui/components/prompt-input';

const host = document.createElement('div');
document.body.append(host);
const prompt = PromptInput.create(host, { label: 'Message' });
let controller: AbortController | null = null;
host.addEventListener('aui-send', () => {
  controller = new AbortController();
  prompt.update({ status: 'streaming' });
  setTimeout(() => {
    prompt.update({ status: 'idle' });
  }, 2000);
});
host.addEventListener('aui-stop', () => {
  controller?.abort();
  prompt.update({ status: 'idle' });
});

import { PromptInput, type PromptSuggestion } from '@absoluteui/components/prompt-input';

const commands: PromptSuggestion[] = [
  { insert: '/summarize', label: '/summarize', description: 'Summarize the conversation' },
  { insert: '/translate', label: '/translate', description: 'Translate the last reply' },
];
const people = ['Ada Lovelace', 'Grace Hopper', 'Alan Turing'];
const host = document.createElement('div');
document.body.append(host);
PromptInput.create(host, {
  label: 'Message',
  triggers: [
    { char: '/', suggest: (query) => commands.filter((c) => c.label.slice(1).startsWith(query)) },
    { char: '@', suggest: (query) => people.filter((p) => p.toLowerCase().includes(query.toLowerCase())).map((p) => ({ insert: `@${p}`, label: p })) },
  ],
});

